# Generated by Claudian.
"""Microphone capture that never stops.

The mic stays open for the entire session, including while JARVIS is talking.
That is the whole point: a system that closes its mic to speak cannot be
interrupted, and one that cannot be interrupted is not a conversation.

Capture runs on PortAudio's callback thread and pushes frames into a queue.
The consumer reads at its own pace. Anything slow — network, synthesis,
inference — happens on other threads, because blocking the callback drops
audio and PortAudio does not tell you it happened.
"""

from __future__ import annotations

import queue
import threading
from typing import Iterator, Optional

import numpy as np

from .vad import FRAME_BYTES, FRAME_SAMPLES, SAMPLE_RATE


class Microphone:
    """Continuous 16 kHz mono capture, yielded as fixed VAD-sized frames."""

    def __init__(self, device: Optional[int] = None, max_queue: int = 200):
        self.device = device
        self._q: queue.Queue[bytes] = queue.Queue(maxsize=max_queue)
        self._stream = None
        self._running = False
        self._dropped = 0
        self._lock = threading.Lock()

    # ── lifecycle ────────────────────────────────────────────────────────

    def start(self) -> None:
        if self._running:
            return
        import sounddevice as sd

        def callback(indata, frames, time_info, status):
            # `status` carries overflow/underflow flags. Printing per frame
            # would itself cause overflows, so just count them.
            if status:
                with self._lock:
                    self._dropped += 1
            try:
                self._q.put_nowait(bytes(indata))
            except queue.Full:
                # Drop the oldest rather than the newest: stale audio is
                # worthless, and blocking here would stall the whole device.
                try:
                    self._q.get_nowait()
                    self._q.put_nowait(bytes(indata))
                except queue.Empty:
                    pass

        self._stream = sd.RawInputStream(
            samplerate=SAMPLE_RATE,
            blocksize=FRAME_SAMPLES,     # exactly one VAD frame per callback
            device=self.device,
            dtype="int16",
            channels=1,
            callback=callback,
        )
        self._stream.start()
        self._running = True

    def stop(self) -> None:
        self._running = False
        if self._stream is not None:
            try:
                self._stream.stop()
                self._stream.close()
            except Exception:
                pass
            self._stream = None

    def __enter__(self):
        self.start()
        return self

    def __exit__(self, *exc):
        self.stop()

    # ── consumption ──────────────────────────────────────────────────────

    def frames(self, timeout: float = 0.5) -> Iterator[bytes]:
        """Yield frames until stopped. Blocks while waiting."""
        while self._running:
            try:
                frame = self._q.get(timeout=timeout)
            except queue.Empty:
                continue
            # sounddevice honours blocksize, but a final partial block on
            # shutdown would crash webrtcvad, which rejects odd lengths.
            if len(frame) == FRAME_BYTES:
                yield frame

    def drain(self) -> int:
        """Discard everything buffered. Called after JARVIS finishes speaking
        so its own tail is not transcribed as the user's next sentence."""
        n = 0
        while True:
            try:
                self._q.get_nowait()
                n += 1
            except queue.Empty:
                return n

    @property
    def stats(self) -> dict:
        with self._lock:
            return {"queued": self._q.qsize(), "dropped_callbacks": self._dropped}


def pcm_to_wav(pcm: bytes, sample_rate: int = SAMPLE_RATE) -> bytes:
    """Wrap raw PCM in a WAV header.

    Whisper needs a container, not bare samples. Building the 44-byte header
    by hand avoids a soundfile/libsndfile dependency for something this small.
    """
    import struct

    n = len(pcm)
    return b"".join((
        b"RIFF", struct.pack("<I", 36 + n), b"WAVEfmt ",
        struct.pack("<IHHIIHH", 16, 1, 1, sample_rate, sample_rate * 2, 2, 16),
        b"data", struct.pack("<I", n), pcm,
    ))


def duration_of(pcm: bytes, sample_rate: int = SAMPLE_RATE) -> float:
    return len(pcm) / 2 / sample_rate


def peak_of(pcm: bytes) -> float:
    a = np.frombuffer(pcm, dtype=np.int16)
    return float(np.abs(a).max()) / 32768.0 if a.size else 0.0
